n118.content:
\begin{theorem}[Main Theorem (very important)]
    \label{thm:main}
    \leanok
    \uses{prop:strictly_additive,prop:commutes_with_inf,prop:reductive}
    For any measure on a local $X$, the caratheodory extension is
    \begin{enumerate}
        \item strictly additiv, i.e. $\mu (A \cup B) = \mu(A) + \mu(B) - \mu(A \cap B)$ for all $A,B\in X$,
        \item commutes with inf $\mu (\inf_{i\in\mathbb{N}} A_i) = \inf_{i\in\mathbb{N}} \mu(A_i)$ for a familiy $(A_i)_{i\in\mathbb{N}}$ of elements $A_i\in X$,
        \item reductive, i.e. for all $A \le X$ the set $\{A' \subset A, \mu(A') = \mu(A)\}$ has a minimal element.
    \end{enumerate}
\end{theorem}

